'use strict';

const fs = require('node:fs');
const path = require('node:path');
const esbuild = require('esbuild');
const { assembleLegacy } = require('./lib/renderer-parts.cjs');

const root = path.resolve(__dirname, '..');
const partsDirectory = path.join(root, 'src/renderer/js/app-parts');

async function buildApp() {
  const files = JSON.parse(
    fs.readFileSync(path.join(root, 'src/renderer/legacy-parts.json'), 'utf8'),
  );
  const header = [
    'import { CodeOSSController } from ' +
      JSON.stringify(path.join(root, 'src/renderer/core/codeoss.ts')) +
      ';',
    'import { activatePage, DockPanels, setDisclosureOpen, motionEnabled, installMotionPreferences } from ' +
      JSON.stringify(path.join(root, 'src/renderer/core/surfaces.ts')) +
      ';',
    'import { TodoSidebar } from ' +
      JSON.stringify(path.join(root, 'src/renderer/core/todo-sidebar.ts')) +
      ';',
    'import { calculateTokenCost } from ' +
      JSON.stringify(path.join(root, 'src/shared/pricing.ts')) +
      ';',
    'import { waitForDependency, reportBootstrapFailure } from ' +
      JSON.stringify(path.join(root, 'src/renderer/core/bootstrap.ts')) +
      ';',
    'const appReady = (async function appEntry() {',
  ].join('\n');
  // The compatibility layer retains its lexical scope while features migrate to imports.
  // Never normalize whitespace inside source: that changes template literal contents.
  const assembled = assembleLegacy(partsDirectory, files, header);
  await esbuild.build({
    stdin: {
      contents: assembled,
      resolveDir: root,
      sourcefile: path.join(root, 'src/renderer/js/legacy-entry.js'),
      loader: 'js',
    },
    outfile: path.join(root, 'src/renderer/js/app.js'),
    bundle: true,
    format: 'esm',
    platform: 'browser',
    target: 'chrome140',
    sourcemap: true,
    sourcesContent: true,
    treeShaking: false,
    logOverride: { 'duplicate-object-key': 'error' },
    banner: {
      js: '/* Generated by esbuild. Edit source modules, not this file. */',
    },
  });
  await esbuild.build({
    entryPoints: [path.join(root, 'src/shared/pricing.ts')],
    outfile: path.join(root, 'src/shared/generated/pricing.cjs'),
    bundle: true,
    platform: 'node',
    format: 'cjs',
    target: 'node24',
    sourcemap: true,
  });
  const preloadDirectory = path.join(root, 'src/preload');
  const preloads = fs
    .readdirSync(preloadDirectory)
    .filter((file) => file === 'preload.js' || file.endsWith('-preload.js'));
  await esbuild.build({
    entryPoints: preloads.map((file) => path.join(preloadDirectory, file)),
    outdir: path.join(preloadDirectory, 'generated'),
    bundle: true,
    platform: 'node',
    format: 'cjs',
    target: 'node24',
    external: ['electron'],
    sourcemap: true,
  });
  require('./build-info')();
  await esbuild.build({
    entryPoints: [path.join(root, 'src/main/vm/guest-tool-worker.js')],
    outfile: path.join(root, 'src/main/vm/generated/guest-tool-worker.cjs'),
    bundle: true,
    platform: 'node',
    format: 'cjs',
    target: 'node22',
    external: [
      'pdf-parse',
      'pdfjs-dist/*',
      'tesseract.js',
      'puppeteer',
      '@napi-rs/canvas',
      'ffmpeg-static',
      'ffprobe-static',
      'electron',
      'eslint',
      'eslint/*',
    ],
    logLevel: 'warning',
  });
  console.log(
    '[build] Built renderer, shared TypeScript and ' +
      preloads.length +
      ' sandboxed preloads (' +
      files.length +
      ' legacy parts)',
  );
}

if (require.main === module)
  buildApp().catch((error) => {
    console.error(error);
    process.exitCode = 1;
  });
module.exports = { buildApp };
